examples.setupTemplate:
val dayStart = {{day|millis}}
var day by rememberSaveable { mutableStateOf<Long?>(dayStart) }
var selection by rememberSaveable { mutableStateOf<Long?>(null) }
var zone by rememberSaveable { mutableStateOf({{timeZone}}) }
val slots = listOf(
    MonarchSlotPickerSlot(start = (day ?: dayStart) + ({{slots.0.start|millis}} - dayStart)),
    MonarchSlotPickerSlot(start = (day ?: dayStart) + ({{slots.1.start|millis}} - dayStart)),
    MonarchSlotPickerSlot(start = (day ?: dayStart) + ({{slots.2.start|millis}} - dayStart), enabled = !{{slots.2.disabled}}),
    MonarchSlotPickerSlot(start = (day ?: dayStart) + ({{slots.3.start|millis}} - dayStart)),
    MonarchSlotPickerSlot(start = (day ?: dayStart) + ({{slots.4.start|millis}} - dayStart), seatsLeft = {{slots.4.seatsLeft}}),
    MonarchSlotPickerSlot(start = (day ?: dayStart) + ({{slots.5.start|millis}} - dayStart)),
)
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

